/* ===================== BÀI 46 · DAC ngoài và lọc số đơn giản ===================== */
/* Bài 46 · DAC ngoài và lọc số đơn giản (AMTS-EMB-001-M12-L02, MC51-046) — sinh bởi tools/author/mcu8051/l46.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 (thiết bị ảo đo lường/điều khiển tải: platform/js/56-mcu51-ana.js) và bài tập chấm tự động. Lời giải không nằm ở đây. */
const P46=[{"label":"Ví dụ: Sóng răng cưa 256 bậc, 3 chu kỳ/bậc","code":"; Sóng răng cưa: tăng mã DAC từng bậc, một chu kỳ 256 bậc\n        ORG     0000H\n        MOV     P2,#00H\n        MOV     R7,#0                   ; DJNZ từ 0: lặp 256 lần\nLAP:    INC     P2                      ; bậc kế tiếp: +20 mV\n        DJNZ    R7,LAP                  ; 1 + 2 = 3 chu kỳ mỗi bậc\n        SJMP    $\n        END\n","note":"Mỗi bậc INC P2 + DJNZ = 3 chu kỳ máy; 256 bậc = 768 µs, tức sóng răng cưa ≈ 1 302 Hz nếu lặp mãi. Bấm Chạy và xem đồ thị DAC; tổng tới SJMP $ là 2 + 1 + 256 × 3 = 771 chu kỳ.","dev":{"dac":true},"fosc":12000000},{"label":"Ví dụ: Sóng sin 16 điểm từ bảng MOVC","code":"; Một chu kỳ sóng sin 16 điểm lấy từ bảng trong bộ nhớ CODE\n        ORG     0000H\n        MOV     DPTR,#BANG\n        MOV     R7,#16                  ; số điểm\n        MOV     R6,#0                   ; chỉ số điểm\nLAP:    MOV     A,R6\n        MOVC    A,@A+DPTR               ; A = BANG[R6]\n        MOV     P2,A                    ; xuất ra DAC\n        INC     R6\n        DJNZ    R7,LAP                  ; 7 chu kỳ mỗi điểm\n        SJMP    $\nBANG:   DB      128,177,218,245,255,245,218,177\n        DB      128,79,38,11,1,11,38,79\n        END\n","note":"MOVC A,@A+DPTR đọc điểm thứ R6 của bảng sin 16 điểm. Mỗi điểm 7 chu kỳ máy (bảng DAC ghi “cách 7 CK”), một chu kỳ sin 112 µs. Đoán trước: sau điểm cuối, P2 bằng bao nhiêu? (4FH = 79.)","dev":{"dac":true},"fosc":12000000},{"label":"Ví dụ: Trung bình 4 mẫu với tổng 16 bit","code":"; Trung bình 4 mẫu 30H..33H: tổng 16 bit R2:A, chia 4\n        ORG     0000H\n        MOV     30H,#0C8H               ; 200\n        MOV     31H,#0CAH               ; 202\n        MOV     32H,#0C5H               ; 197\n        MOV     33H,#0CDH               ; 205\n        MOV     R0,#30H\n        MOV     R7,#4\n        CLR     A                       ; byte thấp của tổng\n        MOV     R2,A                    ; byte cao của tổng\nCONG:   ADD     A,@R0\n        JNC     KNHO\n        INC     R2                      ; có nhớ: byte cao + 1\nKNHO:   INC     R0\n        DJNZ    R7,CONG\n        MOV     R1,#2                   ; chia 4 = dịch phải 2 bit\nDICH:   XCH     A,R2\n        CLR     C\n        RRC     A                       ; byte cao >> 1, bit 0 sang C\n        XCH     A,R2\n        RRC     A                       ; byte thấp nhận bit từ C\n        DJNZ    R1,DICH\n        MOV     34H,A                   ; trung bình\n        SJMP    $\n        END\n","note":"Tổng 200 + 202 + 197 + 205 = 804 = 0324H: ba lần cộng có nhớ làm R2 lên 3. Dịch phải 2 bit cặp R2:A cho C9H = 201. Theo dõi cờ CY ở mỗi lệnh RRC.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Cộng tổng trong một byte, mất cờ nhớ","code":"; Bẫy: cộng 4 mẫu trong một byte, bỏ qua cờ nhớ\n        ORG     0000H\n        MOV     30H,#0C8H\n        MOV     31H,#0CAH\n        MOV     32H,#0C5H\n        MOV     33H,#0CDH\n        MOV     A,30H\n        ADD     A,31H                   ; 402: tràn, mất 256\n        ADD     A,32H\n        ADD     A,33H                   ; A = 804 - 3 x 256 = 36\n        RR      A\n        RR      A                       ; \"chia 4\" phần còn lại\n        MOV     34H,A\n        SJMP    $\n        END\n","note":"Cùng 4 mẫu nhưng cộng trong A, bỏ cờ nhớ: A chỉ còn 24H (36), “chia 4” bằng RR ra 09H. Trung bình đúng là 201: tràn tổng làm kết quả sai hoàn toàn mà không có lỗi nào được báo.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: ADC → lọc trung bình mũ → DAC","code":"; ADC -> lọc y = (3y + x) / 4 -> DAC, 8 mẫu\n        ORG     0000H\n        MOV     R5,#0                   ; y: đầu ra bộ lọc\n        MOV     R7,#8                   ; số mẫu\nMAU:    CLR     P3.6\n        SETB    P3.6                    ; ADC bắt đầu chuyển đổi\nCHO:    JB      P3.2,CHO\n        CLR     P3.7\n        MOV     R4,P1                   ; x: mẫu mới\n        SETB    P3.7\n        MOV     A,R5\n        MOV     B,#3\n        MUL     AB                      ; B:A = 3y\n        ADD     A,R4\n        XCH     A,B\n        ADDC    A,#0                    ; A:B = 3y + x (tối đa 10 bit)\n        RRC     A                       ; dịch phải cặp A:B lần 1\n        XCH     A,B\n        RRC     A\n        XCH     A,B\n        CLR     C\n        RRC     A                       ; lần 2\n        XCH     A,B\n        RRC     A                       ; A = (3y + x) / 4\n        MOV     R5,A\n        MOV     P2,A                    ; xuất ra DAC\n        DJNZ    R7,MAU\n        SJMP    $\n        END\n","note":"ADC đọc 8 mẫu 100, 115, 85, 105, 95, 110, 90, 100 (dao động ±15 mã). Đầu ra bộ lọc trên DAC: 19H 2FH 38H 44H 4AH 53H 54H 58H — dao động nhỏ hơn nhiều nhưng tăng chậm từ 0. Mỗi mẫu 128 chu kỳ máy.","dev":{"adc":{"seq":[2.0,2.3,1.7,2.1,1.9,2.2,1.8,2.0]},"dac":true},"fosc":12000000}];
const sim46=makeSim51(document.getElementById("m51-l46"),{id:"s46",presets:P46,ram:256});
makeEx51(document.getElementById("ex-l46"),"l46",[{"t":"Mẫu có dấu sang mã DAC đơn cực","d":"<p>Bộ lọc số cho ra mẫu <b>có dấu<\/b> (bù 2, −128…+127) ở ô <code>30H<\/code>, nhưng DAC 8 bit ở P2 chỉ nhận mã 0…255 (0 V…5,10 V, giả định toàn thang 5,12 V). Muốn mẫu 0 ra giữa thang (mã 80H = 2,56 V), mẫu −128 ra 0 V và +127 ra mã FFH, mã DAC = mẫu + 128. Viết chương trình ghi mã DAC vào <code>31H<\/code> và xuất ra <code>P2<\/code>; ô 30H giữ nguyên.<\/p><p>Ví dụ: <code>30H = 40H<\/code> (+64) → <code>31H = C0H<\/code>, <code>P2 = C0H<\/code>; <code>30H = FFH<\/code> (−1) → <code>7FH<\/code>.<\/p>","start":"; Mẫu có dấu ở 30H (-128..+127) -> mã DAC đơn cực\n        ORG     0000H\n        MOV     A,30H\n        ADD     A,#128                  ; cộng 128 để dời về 0..255?\n        MOV     P2,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":64,"0x31":238}},"expect":{"iram":{"0x30":64,"0x31":192},"ports":{"P2":192}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":128},"ports":{"P2":128}}},{"setup":{"iram":{"0x30":127,"0x31":238}},"expect":{"iram":{"0x30":127,"0x31":255},"ports":{"P2":255}}},{"setup":{"iram":{"0x30":128,"0x31":238}},"expect":{"iram":{"0x30":128,"0x31":0},"ports":{"P2":0}}},{"setup":{"iram":{"0x30":255,"0x31":238}},"expect":{"iram":{"0x30":255,"0x31":127},"ports":{"P2":127}}},{"setup":{"iram":{"0x30":192,"0x31":238}},"expect":{"iram":{"0x30":192,"0x31":64},"ports":{"P2":64}}}]},"hints":["Thử vài giá trị: −128 = 80H phải thành 00H, 0 = 00H thành 80H, +127 = 7FH thành FFH. Chỉ một bit thay đổi theo cùng một quy luật.","Cộng 128 theo modulo 256 (ADD A,#80H) cho cùng kết quả với đảo bit 7 (XRL A,#80H): bit 7 đổi, các bit khác giữ nguyên.","Code mẫu tính đúng mã nhưng quên ghi ô 31H: ghi A vào cả 31H và P2."],"why":"Mã bù 2 và mã nhị phân dời 128 (offset binary) chỉ khác nhau ở bit 7: x + 128 mod 256 = x XOR 80H. Một lệnh XRL A,#80H (1 chu kỳ) đổi được cả dải −128…+127 sang 00H…FFH."},{"t":"Trung bình trượt 4 mẫu","d":"<p>Ô <code>30H<\/code>…<code>37H<\/code> chứa 8 mẫu ADC liên tiếp (không dấu). Tính 5 giá trị trung bình trượt 4 mẫu: <code>40H<\/code> = floor((x0 + x1 + x2 + x3) / 4), <code>41H<\/code> = floor((x1 + … + x4) / 4), …, <code>44H<\/code> = floor((x4 + … + x7) / 4), với x0 = [30H]. Các ô mẫu giữ nguyên. Tổng 4 mẫu có thể tới 1020 nên cần hơn 8 bit.<\/p><p>Ví dụ: 8 mẫu đều là <code>64H<\/code> → 40H…44H đều là <code>64H<\/code>.<\/p>","start":"; Trung bình trượt 4 mẫu: 8 mẫu 30H..37H -> 5 kết quả 40H..44H\n; (code mẫu cộng trong một byte nên sai khi tổng > 255)\n        ORG     0000H\n        MOV     R0,#30H                 ; mẫu đầu của cửa sổ\n        MOV     R1,#40H                 ; nơi ghi kết quả\n        MOV     R7,#5\nCUA:    MOV     A,@R0\n        INC     R0\n        ADD     A,@R0\n        INC     R0\n        ADD     A,@R0\n        INC     R0\n        ADD     A,@R0\n        DEC     R0\n        DEC     R0\n        RR      A\n        RR      A\n        MOV     @R1,A\n        INC     R1\n        DJNZ    R7,CUA\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":100,"0x31":100,"0x32":100,"0x33":100,"0x34":100,"0x35":100,"0x36":100,"0x37":100,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":100,"0x41":100,"0x42":100,"0x43":100,"0x44":100,"0x30":100,"0x31":100,"0x32":100,"0x33":100,"0x34":100,"0x35":100,"0x36":100,"0x37":100}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0}}},{"setup":{"iram":{"0x30":200,"0x31":202,"0x32":197,"0x33":205,"0x34":200,"0x35":208,"0x36":192,"0x37":204,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":201,"0x41":201,"0x42":202,"0x43":201,"0x44":201,"0x30":200,"0x31":202,"0x32":197,"0x33":205,"0x34":200,"0x35":208,"0x36":192,"0x37":204}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":0,"0x41":63,"0x42":127,"0x43":191,"0x44":255,"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":255,"0x35":255,"0x36":255,"0x37":255}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":255,"0x41":255,"0x42":255,"0x43":255,"0x44":255,"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255}}},{"setup":{"iram":{"0x30":16,"0x31":240,"0x32":16,"0x33":240,"0x34":16,"0x35":240,"0x36":16,"0x37":240,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":128,"0x41":128,"0x42":128,"0x43":128,"0x44":128,"0x30":16,"0x31":240,"0x32":16,"0x33":240,"0x34":16,"0x35":240,"0x36":16,"0x37":240}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":5,"0x35":6,"0x36":7,"0x37":9,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238}},"expect":{"iram":{"0x40":2,"0x41":3,"0x42":4,"0x43":5,"0x44":6,"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":5,"0x35":6,"0x36":7,"0x37":9}}}]},"hints":["Code mẫu cộng trong A nên mất phần vượt 255: với mẫu C8H… kết quả sai hẳn (bộ thử 3).","Giữ byte cao của tổng trong R2: sau mỗi ADD, nếu CY = 1 thì INC R2. Chia 4 = dịch phải cặp R2:A hai lần bằng RRC (nhớ CLR C trước khi dịch byte cao).","Mỗi cửa sổ bắt đầu sau cửa sổ trước đúng một mẫu: giữ vị trí bắt đầu ở chỗ riêng để không mất nó khi cộng."],"why":"Mỗi trung bình cần tổng 10 bit (tối đa 4 × 255 = 1020), nên phải mang cờ nhớ sang byte cao rồi dịch cả cặp. Trung bình trượt giảm dao động ngẫu nhiên nhưng làm tín hiệu trễ: một bước nhảy cần đủ 4 mẫu mới hiện hết ở đầu ra (bộ thử 4)."},{"t":"Trung bình 8 mẫu dưới 42 chu kỳ","d":"<p>Tính trung bình 8 mẫu <code>30H<\/code>…<code>37H<\/code>: <code>38H<\/code> = floor(tổng / 8); các ô mẫu giữ nguyên. Code mẫu đúng nhưng dùng vòng lặp 8 lần và 3 lần dịch phải cặp R2:A, mất khoảng 90 chu kỳ. Hãy viết lại để chạy không quá <b>42 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>52 byte<\/b>.<\/p><p>Ví dụ: tám mẫu đều <code>FFH<\/code> → tổng 7F8H → <code>38H = FFH<\/code>.<\/p>","start":"; Trung bình 8 mẫu 30H..37H -> 38H. Đúng nhưng chậm:\n; vòng lặp 8 lần, rồi dịch phải 3 lần cặp R2:A.\n        ORG     0000H\n        MOV     R0,#30H\n        MOV     R7,#8\n        CLR     A\n        MOV     R2,A\nCONG:   ADD     A,@R0\n        JNC     KN\n        INC     R2\nKN:     INC     R0\n        DJNZ    R7,CONG\n        MOV     R7,#3\nDICH:   XCH     A,R2\n        CLR     C\n        RRC     A\n        XCH     A,R2\n        RRC     A\n        DJNZ    R7,DICH\n        MOV     38H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":238}},"expect":{"iram":{"0x38":255,"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":238}},"expect":{"iram":{"0x38":0,"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0}}},{"setup":{"iram":{"0x30":100,"0x31":100,"0x32":100,"0x33":100,"0x34":100,"0x35":100,"0x36":100,"0x37":100,"0x38":238}},"expect":{"iram":{"0x38":100,"0x30":100,"0x31":100,"0x32":100,"0x33":100,"0x34":100,"0x35":100,"0x36":100,"0x37":100}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":5,"0x35":6,"0x36":7,"0x37":8,"0x38":238}},"expect":{"iram":{"0x38":4,"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":5,"0x35":6,"0x36":7,"0x37":8}}},{"setup":{"iram":{"0x30":200,"0x31":202,"0x32":197,"0x33":205,"0x34":200,"0x35":208,"0x36":192,"0x37":204,"0x38":238}},"expect":{"iram":{"0x38":201,"0x30":200,"0x31":202,"0x32":197,"0x33":205,"0x34":200,"0x35":208,"0x36":192,"0x37":204}}},{"setup":{"iram":{"0x30":128,"0x31":127,"0x32":128,"0x33":127,"0x34":128,"0x35":127,"0x36":128,"0x37":129,"0x38":238}},"expect":{"iram":{"0x38":127,"0x30":128,"0x31":127,"0x32":128,"0x33":127,"0x34":128,"0x35":127,"0x36":128,"0x37":129}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":255,"0x33":0,"0x34":255,"0x35":0,"0x36":255,"0x37":7,"0x38":238}},"expect":{"iram":{"0x38":128,"0x30":255,"0x31":0,"0x32":255,"0x33":0,"0x34":255,"0x35":0,"0x36":255,"0x37":7}}}],"maxCyc":42,"maxBytes":52},"hints":["Vòng lặp tốn INC R0 và DJNZ (3 chu kỳ) cho mỗi mẫu: trải vòng lặp, dùng ADD A,31H … ADD A,37H với địa chỉ trực tiếp.","Tổng lớn nhất 2040 = 7F8H: byte cao chỉ 0…7. Kết quả = (byte cao × 32) OR (byte thấp / 8).","Chia 8 không cần dịch từng bit: tổ hợp SWAP với một lệnh xoay. Hai byte của tổng góp vào kết quả theo hai cách khác nhau."],"why":"Trải vòng lặp bỏ được 8 lần INC R0 + DJNZ. Chia cho 8 không cần 3 lần dịch 16 bit (mỗi lần 5 lệnh): vì byte cao ≤ 7, kết quả = (cao &lt;&lt; 5) | (thấp &gt;&gt; 3), mỗi phép dịch là SWAP + RL (2 chu kỳ). Lời giải tham chiếu: 40 chu kỳ khi cả 7 phép cộng đều có nhớ, 51 byte."}]);

makeQuiz("quiz46","score46",[{"q": "DAC 8 bit, toàn thang 5,12 V (Vout = mã × 5,12 / 256). Ghi mã C8H thì Vout bằng bao nhiêu?", "o": ["4,02 V", "5,12 V", "4,00 V", "2,00 V"], "a": 2, "e": "C8H = 200; 200 × 20 mV = 4,00 V. 4,02 V là kết quả khi nhầm chia cho 255; 2,00 V là mã 64H."}, {"q": "Vòng INC P2 / DJNZ R7,LAP (3 chu kỳ mỗi bậc, 256 bậc) ở 12 MHz cho sóng răng cưa tần số khoảng bao nhiêu?", "o": ["3,9 kHz", "1,3 kHz", "333 kHz", "47 kHz"], "a": 1, "e": "Một chu kỳ sóng = 256 × 3 µs = 768 µs → ≈ 1 302 Hz. 333 kHz là tần số cập nhật từng bậc (3 µs), không phải tần số sóng."}, {"q": "Cộng 4 mẫu C8H, CAH, C5H, CDH trong thanh ghi A bằng ADD (bỏ qua cờ nhớ) rồi xoay phải 2 lần. Kết quả?", "o": ["C9H — đúng trung bình", "FFH — bão hòa", "24H — chỉ thiếu bước chia", "09H — sai vì mất 3 × 256 khi tràn"], "a": 3, "e": "Tổng thật 804 = 0324H; A chỉ giữ 24H, xoay 2 lần ra 09H. Phải mang cờ nhớ sang byte cao (R2) rồi dịch cả cặp R2:A."}, {"q": "Bộ lọc y ← (3y + x)/4 với phép chia làm tròn xuống, x luôn = 100, y đang = 97. Lần cập nhật tiếp theo cho y bằng?", "o": ["97 — bộ lọc kẹt, sai số dừng 3 mã", "98", "100", "99"], "a": 0, "e": "(3 × 97 + 100)/4 = 391/4 = 97,75 → làm tròn xuống 97: y không tăng nữa. Cộng 2 trước khi dịch (làm tròn gần nhất) giảm sai số dừng xuống 1 mã."}, {"q": "Mẫu có dấu −1 (FFH, bù 2) cần ra DAC đơn cực sao cho 0 ứng với giữa thang. Mã DAC là?", "o": ["FFH", "81H", "7FH", "01H"], "a": 2, "e": "Mã = mẫu + 128 = −1 + 128 = 127 = 7FH; tương đương FFH XOR 80H = 7FH."}]);

